import React, { useState } from 'react';
import { Link } from 'react-router-dom';

type Student = {
  id: string;
  rollNumber: string;
  name: string;
  email: string;
  department: string;
};

export default function StudentSearchPage() {
  const [rollNumber, setRollNumber] = useState('');
  const [student, setStudent] = useState<Student | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    try {
      const response = await fetch(`http://localhost:5000/api/students/search?rollNumber=${rollNumber}`);
      if (!response.ok) throw new Error('Search failed');
      const data = await response.json();
      setStudent(data);
    } catch (error) {
      setError(error instanceof Error ? error.message : 'Search failed');
      setStudent(null);
    } finally {
      setLoading(false);
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setRollNumber(e.target.value);
  };

  return (
    <div className="container mt-5">
      <h1 className="mb-4 text-primary">Student Search</h1>
      <Link to="/students" className="btn btn-secondary mb-4">Back to Students</Link>
      
      <form onSubmit={handleSearch} className="mb-4">
        <div className="form-group mb-3">
          <input
            type="text"
            name="rollNumber"
            className="form-control"
            placeholder="Roll Number"
            value={rollNumber}
            onChange={handleChange}
            required
          />
        </div>
        <button type="submit" className="btn btn-primary">Search</button>
      </form>

      {loading && <div className="text-center my-4">Loading...</div>}
      {error && <div className="alert alert-danger my-4">{error}</div>}
      {student && (
        <div className="card border-primary">
          <div className="card-header bg-primary text-white">
            <h2>Student Details</h2>
          </div>
          <div className="card-body">
            <p><strong>Roll Number:</strong> {student.rollNumber}</p>
            <p><strong>Name:</strong> {student.name}</p>
            <p><strong>Email:</strong> {student.email}</p>
            <p><strong>Department:</strong> {student.department}</p>
          </div>
        </div>
      )}
    </div>
  );
}
